// Strings for the page scripts and the language menu. Each page embeds its
// language's strings as JSON (#i18n-strings), generated by scripts/build-site.mjs
// from site-src/i18n/, so scripts never carry their own copy of the text.
(() => {
  let data = {};
  try { data = JSON.parse(document.getElementById('i18n-strings')?.textContent || '{}'); } catch {}
  const lang = data.lang || document.documentElement.lang || 'en';
  const strings = data.strings || {};
  const plurals = new Intl.PluralRules(lang);

  const get = key => key.split('.').reduce((node, part) => node?.[part], strings);

  // t('game.count', { count: 2 }) picks the plural form for `count`, then fills {placeholders}.
  const t = (key, params = {}) => {
    let text = get(key);
    if (text && typeof text === 'object' && 'other' in text) text = text[plurals.select(params.count ?? 0)] ?? text.other;
    if (typeof text !== 'string') return key;
    return text.replace(/\{(\w+)\}/g, (match, name) => (name in params ? String(params[name]) : match));
  };

  window.vantoI18n = { lang, code: data.code || 'en', root: data.root || '/', t, get };

  // Language menu: a <details> disclosure that works without JS; this adds
  // Escape, outside-click closing, the current #section, and a remembered choice.
  const menu = document.querySelector('.lang-menu');
  if (menu) {
    const toggle = menu.querySelector('summary');
    menu.addEventListener('keydown', event => {
      if (event.key !== 'Escape' || !menu.open) return;
      menu.open = false;
      toggle.focus();
    });
    document.addEventListener('click', event => {
      if (menu.open && !menu.contains(event.target)) menu.open = false;
    });
    menu.addEventListener('focusout', event => {
      if (menu.open && event.relatedTarget && !menu.contains(event.relatedTarget)) menu.open = false;
    });
  }

  document.addEventListener('click', event => {
    const link = event.target.closest?.('a[data-lang]');
    if (!link) return;
    if (link.getAttribute('aria-current') === 'true') {
      event.preventDefault();
      if (menu) menu.open = false;
      return;
    }
    try { localStorage.setItem('vanto-lang', link.dataset.lang); } catch {}
    if (location.hash && !link.hash) link.hash = location.hash;
  });
})();
